import java.awt.*;import java.awt.image.*;import java.nio.file.*;import javax.imageio.ImageIO;
public class GenerateWordmark{public static void main(String[]a)throws Exception{var font=Font.createFont(Font.TRUETYPE_FONT,Path.of(a[0]).toFile()).deriveFont(176f);var probe=new BufferedImage(1,1,2);var g=probe.createGraphics();var frc=g.getFontRenderContext();var glyph=font.createGlyphVector(frc,"EVATEX");var shape=glyph.getOutline();var b=shape.getBounds2D();int pad=12;var im=new BufferedImage((int)Math.ceil(b.getWidth())+pad*2,(int)Math.ceil(b.getHeight())+pad*2,2);g=im.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(Color.WHITE);g.translate(pad-b.getX(),pad-b.getY());g.fill(shape);g.dispose();for(int y=0;y<im.getHeight();y++)for(int x=0;x<im.getWidth();x++)im.setRGB(x,y,(im.getRGB(x,y)&0xff000000)|0x00ffffff);ImageIO.write(im,"png",Path.of(a[1]).toFile());System.out.println(im.getWidth()+"x"+im.getHeight());}}
